"""TOEIC Part 5 bank batch 4: original customer service and finance items."""
from lib import P5


P5("The bank will waive the monthly fee for customers who maintain a ___ balance.", ["minimum", "minimize", "minimally", "minimization"], "pos",
   "Cần tính từ minimum đứng trước danh từ balance.", "money_banking", 3,
   expl_en="An adjective is required before balance. Minimum describes the lowest required amount.")
P5("The cashier counted the money twice to ensure that the amount was ___.", ["accurate", "accuracy", "accurately", "accumulate"], "pos",
   "Sau was cần tính từ accurate để mô tả amount.", "money_banking", 2,
   expl_en="The linking verb was takes an adjective. Accurate describes an amount that is correct.")
P5("The company offers customers several convenient payment ___.", ["methods", "methodical", "methodically", "method"], "pos",
   "Several cần danh từ số nhiều methods.", "money_banking", 2,
   expl_en="Several requires a plural countable noun. Methods are different ways to pay.")
P5("The invoice includes a charge ___ late payment.", ["for", "of", "to", "with"], "preposition",
   "Charge for là cụm chỉ khoản phí cho việc gì.", "accounting", 2,
   expl_en="Charge for is the correct collocation for a fee connected with late payment.")
P5("The accountant noticed that one receipt was missing from the expense ___.", ["report", "reporting", "reported", "reporter"], "pos",
   "Expense report là cụm danh từ; sau the cần report.", "accounting", 2,
   expl_en="Expense report is the standard noun phrase for a record of spending.")
P5("The finance team has not finalized the figures ___, so please wait.", ["yet", "already", "still", "ever"], "adverb",
   "Yet thường dùng trong câu phủ định hiện tại hoàn thành để nói chưa xảy ra.", "finance", 3,
   expl_en="Yet is commonly used in negative present perfect sentences to say that something has not happened up to now.")
P5("The customer asked whether the transfer could be completed ___.", ["electronically", "electronic", "electronics", "electron"], "pos",
   "Completed là động từ nên cần trạng từ electronically.", "money_banking", 3,
   expl_en="Electronically is an adverb describing how the transfer can be completed.")
P5("The store offers a full refund provided that the item is returned ___.", ["unused", "use", "using", "uses"], "pos",
   "Sau is returned cần tính từ unused mô tả tình trạng món đồ.", "shopping", 3,
   expl_en="Unused is an adjective describing an item that has not been used, a condition for the refund.")
P5("The credit department will review the application before a decision ___.", ["is made", "makes", "made", "will make"], "passive",
   "Decision nhận hành động nên dùng bị động is made; sau before không dùng will.", "money_banking", 4,
   expl_en="A decision receives the action, so the passive is is made. A future time clause after before uses present simple.")
P5("The retailer sends customers an email as soon as their order ___.", ["ships", "ship", "shipped", "will ship"], "agreement",
   "Order số ít nên dùng ships; sau as soon as dùng hiện tại đơn.", "shopping", 2,
   expl_en="Order is singular, so the present simple form is ships. A future time clause after as soon as uses present simple.")
P5("The contract specifies that payment must be made ___ thirty days.", ["within", "during", "among", "beside"], "preposition",
   "Within thirty days nghĩa là trong vòng 30 ngày.", "legal", 3,
   expl_en="Within gives the deadline period: payment must occur before the end of thirty days.")
P5("The company is unable to process orders ___ the system is offline.", ["while", "despite", "because of", "during"], "conjunction",
   "While nối mệnh đề the system is offline và chỉ thời gian hệ thống ngừng hoạt động.", "tech", 3,
   expl_en="While introduces a complete clause and gives the time during which orders cannot be processed.")
P5("The customer service agent handled the complaint with great ___.", ["patience", "patient", "patiently", "impatient"], "pos",
   "With great cần danh từ patience.", "sales", 2,
   expl_en="With great is followed by a noun. Patience describes the calm way the complaint was handled.")
P5("The company apologized for the inconvenience and offered to replace the item ___.", ["immediately", "immediate", "immediacy", "immediate action"], "pos",
   "Replace là động từ cần trạng từ immediately.", "sales", 2,
   expl_en="Immediately is an adverb modifying replace and tells when the company offered to act.")
P5("The payment terminal is temporarily unavailable; please use another one ___.", ["instead", "instead of", "rather", "substitute"], "adverb",
   "Instead đứng cuối câu để chỉ lựa chọn thay thế.", "shopping", 3,
   expl_en="Instead is an adverb used at the end of the sentence to show an alternative.")
P5("The supervisor asked the clerk to verify the customer's identity ___.", ["personally", "personal", "personality", "person"], "pos",
   "Verify là động từ nên cần trạng từ personally.", "money_banking", 3,
   expl_en="Personally is an adverb modifying verify and means the clerk should do it directly.")
P5("The new account can be opened online without an appointment, ___?", ["can't it", "can it", "doesn't it", "isn't it"], "tag_question",
   "Mệnh đề chính có can be opened dạng khẳng định nên câu hỏi đuôi là can't it.", "money_banking", 4,
   expl_en="The statement is affirmative and uses the modal can, so the negative tag is can't it.")
P5("The receipt should be kept until the warranty period ___.", ["expires", "expire", "expired", "will expire"], "agreement",
   "Warranty period số ít nên dùng expires; sau until dùng hiện tại đơn.", "shopping", 3,
   expl_en="Warranty period is singular, and the time clause after until takes present simple expires.")
P5("The payment was rejected because the account contained ___ funds.", ["insufficient", "insufficiency", "insufficiently", "suffice"], "pos",
   "Funds cần tính từ insufficient để nói không đủ tiền.", "money_banking", 3,
   expl_en="Insufficient is an adjective describing funds that are not enough.")
P5("The finance manager is responsible for ensuring that all records are kept ___.", ["securely", "secure", "security", "securing"], "pos",
   "Kept là động từ cần trạng từ securely để chỉ cách lưu giữ.", "accounting", 3,
   expl_en="Securely is an adverb modifying kept and describes how records must be stored.")
P5("The store will extend its return policy ___ the holiday season.", ["throughout", "between", "among", "toward"], "preposition",
   "Throughout đi trước khoảng thời gian the holiday season.", "shopping", 3,
   expl_en="Throughout means during the whole period of the holiday season.")
P5("The manager gave the customer a clear explanation, ___ the customer remained dissatisfied.", ["but", "because", "so that", "unless"], "conjunction",
   "But nối hai mệnh đề tương phản.", "sales", 2,
   expl_en="But connects the contrasting ideas of a clear explanation and continued dissatisfaction.")
P5("The bank's website has been redesigned to make navigation more ___.", ["intuitive", "intuition", "intuitively", "intuit"], "pos",
   "Sau make navigation more cần tính từ intuitive.", "tech", 3,
   expl_en="More modifies the adjective intuitive, describing navigation that is easy to understand.")
P5("The customer requested that the disputed charge ___ immediately.", ["be removed", "is removed", "removed", "removing"], "subjunctive",
   "Sau requested that dùng bị động nguyên mẫu be removed.", "money_banking", 4,
   expl_en="After requested that, formal English uses the base subjunctive be removed for the requested action.")
P5("Please contact the help desk if you have any difficulty ___ the payment.", ["making", "make", "made", "to make"], "gerund",
   "Difficulty đi với V-ing; making a payment là cụm phù hợp.", "money_banking", 3,
   expl_en="Difficulty is followed by a gerund. Making the payment names the activity causing difficulty.")
P5("The store manager will investigate the matter and respond as ___ as possible.", ["soon", "sooner", "soonest", "soonness"], "comparison",
   "Cụm as soon as possible cần tính từ/trạng từ nguyên cấp soon.", "sales", 2,
   expl_en="The fixed expression is as soon as possible, using the base form soon between as and as.")
P5("The accountant checked the totals again to avoid an ___ error.", ["avoidable", "avoid", "avoiding", "avoidance"], "pos",
   "An ___ error cần tính từ avoidable, nghĩa là có thể tránh được.", "accounting", 3,
   expl_en="An adjective is needed before error. Avoidable describes an error that could have been prevented.")
P5("The payment instructions are available in several languages for the convenience of ___.", ["customers", "customer", "customary", "customize"], "pos",
   "For the convenience of cần danh từ hoặc đại từ; customers phù hợp ngữ cảnh số nhiều.", "money_banking", 2,
   expl_en="The preposition of needs a noun. Customers are the people who benefit from the translated instructions.")
P5("The company will issue a replacement once the damaged product ___.", ["is received", "receives", "received", "will receive"], "passive",
   "Damaged product nhận hành động nhận lại nên dùng is received; sau once không dùng will.", "shopping", 3,
   expl_en="The product receives the action, so is received is passive. A future time clause after once uses present simple.")
P5("The retailer is known for responding to customer inquiries ___.", ["promptly", "prompt", "promptness", "prompted"], "pos",
   "Responding là động từ cần trạng từ promptly.", "sales", 2,
   expl_en="Promptly is an adverb describing how quickly the retailer responds.")
P5("The bank will notify account holders ___ there is any unusual activity.", ["if", "despite", "during", "because of"], "conjunction",
   "If mở đầu điều kiện có hoạt động bất thường.", "money_banking", 2,
   expl_en="If introduces the condition that triggers the bank's notification.")
